import { getLocalData } from '../utils/storage';

function Profile() {
  const currentUser = getLocalData('currentUser');

  if (!currentUser) {
    return <p style={{ color: '#888' }}>Không tìm thấy thông tin người dùng.</p>;
  }

  const rows = [
    { label: 'Họ tên', value: currentUser.name || '--' },
    { label: 'Tên đăng nhập', value: currentUser.username || '--' },
    { label: 'Vai trò', value: currentUser.role === 'admin' ? 'Quản trị viên' : 'Nhân viên' },
    { label: 'Email', value: currentUser.email || 'Chưa cập nhật' },
    { label: 'Số điện thoại', value: currentUser.phone || 'Chưa cập nhật' },
    { label: 'Phòng ban', value: currentUser.department || 'Chưa cập nhật' },
  ];

  return (
    <div>
      <h4 style={{ marginBottom: '4px', color: '#111' }}>Hồ sơ cá nhân</h4>
      <p style={{ color: '#888', fontSize: '14px', marginBottom: '20px' }}>
        Thông tin tài khoản của bạn.
      </p>

      <div style={{ display: 'flex', gap: '24px', alignItems: 'flex-start', flexWrap: 'wrap' }}>
        {/* Avatar */}
        <div style={{
          backgroundColor: '#fff',
          border: '1px solid #ddd',
          borderRadius: '8px',
          padding: '24px',
          textAlign: 'center',
          minWidth: '180px'
        }}>
          <div style={{
            width: '72px',
            height: '72px',
            borderRadius: '50%',
            backgroundColor: '#2563eb',
            color: '#fff',
            fontSize: '28px',
            fontWeight: 'bold',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            margin: '0 auto 12px'
          }}>
            {(currentUser.name || currentUser.username || 'U').charAt(0).toUpperCase()}
          </div>
          <p style={{ margin: 0, fontWeight: '600', color: '#222' }}>
            {currentUser.name || currentUser.username}
          </p>
          <p style={{ margin: '4px 0 0', fontSize: '12px', color: '#888' }}>
            {currentUser.role === 'admin' ? 'Quản trị viên' : 'Nhân viên'}
          </p>
        </div>

        {/* Thông tin chi tiết */}
        <div style={{
          backgroundColor: '#fff',
          border: '1px solid #ddd',
          borderRadius: '8px',
          padding: '24px',
          flex: 1,
          minWidth: '280px'
        }}>
          <h6 style={{ marginBottom: '16px', color: '#333' }}>Thông tin tài khoản</h6>
          {rows.map((row) => (
            <div key={row.label} style={{
              display: 'flex',
              padding: '10px 0',
              borderBottom: '1px solid #f0f0f0',
              fontSize: '14px'
            }}>
              <span style={{ color: '#888', width: '160px', flexShrink: 0 }}>{row.label}</span>
              <span style={{ color: '#222' }}>{row.value}</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

export default Profile;
